local R=dofile('tests/kernel_npcs_harness.lua')
local n=0
local function case(name,fn)R.clientCase(name,fn);n=n+1 end
local function spawn(r,p)r.value=p or R.seed();r.tick();return r.npcs.get(1)end
local function count(r)local n=0;for _ in pairs(r.entities)do n=n+1 end;return n end
local placement={x=8.12345,y=9.23456,z=10.34567,heading=-30}
case('empty worker',function(r)assert(r.tick()==1200 and count(r)==0)end)
case('near ped actual PR streaming',function(r)local e=spawn(r);assert(e.handle==101 and r.targets[101]and r.headings[101]==60)end)
case('far ped',function(r)local p=R.seed();p.npcs[1].coords.x=999;spawn(r,p);assert(count(r)==0)end)
case('despawn respawn',function(r)spawn(r);r.positions[11]=R.vector(999,0,0);r.tick();assert(count(r)==0 and not r.targets[101]);r.positions[11]=R.vector();r.tick();assert(r.npcs.get(1).handle==102)end)
case('disabled world',function(r)spawn(r);local p=R.seed();p.enabled=false;r.apply(p);r.tick();assert(count(r)==0)end)
case('disabled entry retains existing handle',function(r)spawn(r);local p=R.seed();p.npcs[1].enabled=false;r.apply(p);r.tick();assert(count(r)==1)end)
case('disabled entry initially no spawn',function(r)local p=R.seed();p.npcs[1].enabled=false;spawn(r,p);assert(count(r)==0)end)
case('nil payload removes',function(r)spawn(r);r.apply(nil);assert(count(r)==0 and not r.npcs.get(1))end)
case('bad ids',function(r)r.apply({npcs={{id='bad'},{model='x'}}});assert(next(r.npcs.entries)==nil)end)
case('group sorting',function(r)local p=R.seed();p.npcs[2]={id=5,groupid=1};p.npcs[3]={id=2,groupId=1};r.apply(p);local a=r.npcs.getByGroup('1');assert(a[1].id==1 and a[2].id==2 and a[3].id==5)end)
case('model change deletes and respawns',function(r)spawn(r);local p=R.seed();p.npcs[1].model='new';r.apply(p);assert(count(r)==0);r.tick();assert(r.npcs.get(1).handle==102)end)
case('transform update',function(r)spawn(r);local p=R.seed();p.npcs[1].coords.x=8;p.npcs[1].heading=80;r.apply(p);assert(r.positions[101].x==8 and r.headings[101]==80);r.advance(500);assert(r.targets[101])end)
case('same transform reapplies heading',function(r)spawn(r);r.apply(R.seed());r.advance(500);assert(r.headings[101]==60)end)
case('heading from rotation',function(r)local p=R.seed();p.npcs[1].heading=nil;p.npcs[1].rotation={0,0,-90};spawn(r,p);assert(r.headings[101]==270)end)
case('scenario timers',function(r)local p=R.seed();p.npcs[1].animation={scenario='WORLD_HUMAN_GUARD_STAND'};spawn(r,p);r.advance(1600);assert(r.headings[101]==60)end)
case('animation dictionary PR',function(r)local p=R.seed();p.npcs[1].animation={animDict='dict',animName='name'};spawn(r,p);r.advance(800)end)
case('animation fallback',function(r)r.library.fivem.streaming.requestAnimDict=nil;local p=R.seed();p.npcs[1].animation={animDict='dict',animName='name'};spawn(r,p)end)
for _,access in ipairs({{}, {job='police',grade=2},{job='police',grade=3},{job='other',gang='ballas',gangGrade=1},{job='police',grade=99,gang='ballas',gangGrade=1},{gang='ballas',gangGrade=2}})do
 case('access '..n,function(r)local p=R.seed();p.npcs[1].interaction.access=access;spawn(r,p);return r.targets[101][1].canInteract()end)
end
case('grade scalar and absent group',function(r)r.groups.job={name='police',grade=2};r.groups.gang=nil;local p=R.seed();p.npcs[1].interaction.access={job='police',grade=2};spawn(r,p);assert(r.targets[101][1].canInteract());r.groups.job=nil;assert(not r.targets[101][1].canInteract())end)
local actions={'fixture:talk','/do something','',[[exports['resource']:Run($id, $npc, true, false, 5, 'a,b', "hi")]],'exports.resource:Run(id,entry,2.5,word)',"exports['resource']:Run(nil, 4)",'exports.bad syntax'}
for _,action in ipairs(actions)do case('interaction action '..n,function(r)r.exportTable.resource={Run=function(...)r.record('export-called',...);return false end};local p=R.seed();p.npcs[1].interaction.event=action;spawn(r,p);r.targets[101][1].onSelect()end)end
case('export stopped',function(r)r.resourceStatus='stopped';local p=R.seed();p.npcs[1].interaction.event='exports.resource:Run()';spawn(r,p);r.targets[101][1].onSelect()end)
case('export missing',function(r)local p=R.seed();p.npcs[1].interaction.event='exports.resource:Run()';spawn(r,p);r.targets[101][1].onSelect()end)
case('export throws',function(r)r.exportTable.resource={Run=function()error('fixture-export',0)end};local p=R.seed();p.npcs[1].interaction.event='exports.resource:Run()';spawn(r,p);r.targets[101][1].onSelect()end)
case('onSelect does not repeat access check',function(r)local p=R.seed();p.npcs[1].interaction.access={job='police',grade=99};spawn(r,p);assert(not r.targets[101][1].canInteract());r.targets[101][1].onSelect()end)
case('drawtext pressed',function(r)spawn(r);r.pressed=true;assert(r.tick(2)==0)end)
case('no drawtext while denied',function(r)local p=R.seed();p.npcs[1].interaction.access={job='other'};spawn(r,p);r.pressed=true;assert(r.tick(2)==600)end)
case('debug and outline no-op',function(r)spawn(r);assert(r.npcs.toggleDebug());assert(r.tick(2)==0);assert(r.npcs.setOutline(1,true));assert(not r.npcs.get(1).highlighted);assert(not r.npcs.toggleDebug())end)
case('teleport and missing',function(r)spawn(r);assert(r.npcs.teleportTo(1)and not r.npcs.teleportTo(999));assert(r.positions[11].x==1 and not r.npcs.setOutline(999,true))end)
case('invalid model',function(r)r.validModel=false;spawn(r);assert(count(r)==0)end)
case('zero ped',function(r)r.createZero=true;spawn(r);assert(count(r)==0)end)
case('create native error',function(r)r.createError=true;spawn(r);assert(count(r)==0)end)
case('no devtools',function(r)r.library.devtools=nil;local ok,e=r.npcs.createPreview('m',1);assert(not ok and e=='devtools_unavailable')end)
case('placement confirm serialization',function(r)r.rpcHook=function(_,v)assert(v.coords.x==8.123 and v.coords.y==9.235 and v.heading==-30);return true,99 end;local ok,e=r.npcs.createPreview('m',1,'N','D',function(id)assert(id==99)end);assert(ok and e=='devtools_failed');r.finish(placement);assert(r.npcs.placementActive);r.advance(500);assert(not r.npcs.placementActive and not r.targetDisabled)end)
case('placement cancel',function(r)r.npcs.createPreview('m',1);r.finish(nil);assert(not r.npcs.placementActive and r.targetDisabled);r.advance(250);assert(not r.targetDisabled)end)
case('placement refused',function(r)r.placeFailed=true;local ok,e=r.npcs.createPreview('m',1);assert(not ok and e=='devtools_failed'and not r.targetDisabled)end)
case('placement server failure',function(r)r.npcs.createPreview('m',1);r.rpcHook=function()return false,'save_failed'end;r.finish(placement);r.advance(500)end)
case('placement RPC exception retains active flag',function(r)r.npcs.createPreview('m',1);r.rpcHook=function()error('fixture-rpc',0)end;assert(not pcall(r.finish,placement)and r.npcs.placementActive and r.targetDisabled)end)
case('edit missing',function(r)local ok,e=r.npcs.edit(99);assert(not ok and e=='npc_not_found')end)
case('edit success',function(r)spawn(r);assert(r.npcs.edit(1,function()r.record('updated')end));assert(not r.targets[101]and not r.collisions[101]);r.finish(placement);r.advance(500);assert(r.collisions[101]and not r.npcs.placementActive)end)
case('edit cancel no target immediate',function(r)spawn(r);r.npcs.edit(1);r.finish(nil);r.advance(250);assert(r.collisions[101]and not r.targets[101])end)
case('edit failed start restores',function(r)spawn(r);r.placeFailed=true;assert(not r.npcs.edit(1));assert(r.collisions[101]and not r.targetDisabled)end)
case('edit save failure',function(r)spawn(r);r.npcs.edit(1);r.rpcHook=function()return false,'no_permission'end;r.finish(placement);r.advance(500)end)
case('unrelated stop ignored',function(r)spawn(r);r.stop('other');assert(count(r)==1)end)
case('stop deletes known handles',function(r)spawn(r);r.stop();assert(count(r)==0 and not r.targets[101])end)
case('late placement after stop still sends',function(r)r.npcs.createPreview('m',1);r.stop();r.finish(placement);r.advance(500)end)
case('late streaming after removal',function(r)r.value=R.seed();r.loaded=false;local co=r.run(r.initial[1]);r.apply(nil);r.loaded=true;r.resume(co);assert(count(r)==1 and next(r.npcs.entries)==nil)end)
case('placement suspends spawn worker',function(r)r.value=R.seed();r.npcs.createPreview('m',1);r.tick();assert(count(r)==0);r.finish(nil);r.advance(250);r.tick();assert(count(r)==1)end)
print('PASS NPC renderer/editor/action differentials '..n)
